/** Flat lookup: card id -> { card, deck } (used by the review action). */
export const CARDS_BY_ID: ReadonlyMap<string, { card: Flashcard; deck: FlashcardDeck }> =
  new Map(
    FLASHCARD_DECKS.flatMap((deck) => deck.cards.map((card) => [card.id, { card, deck }]))
  )
